import{_ as l,r as e,o as i,c as r,e as t,a as s,s as p,d as n}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"特征 - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"属性操作","slug":"属性操作","link":"#属性操作","children":[{"level":3,"title":"可空","slug":"可空","link":"#可空","children":[]},{"level":3,"title":"哈希(Hash)","slug":"哈希-hash","link":"#哈希-hash","children":[]},{"level":3,"title":"可清除","slug":"可清除","link":"#可清除","children":[]},{"level":3,"title":"可加密","slug":"可加密","link":"#可加密","children":[]},{"level":3,"title":"别名","slug":"别名","link":"#别名","children":[]}]},{"level":2,"title":"排序和重新排序","slug":"排序和重新排序","link":"#排序和重新排序","children":[{"level":3,"title":"可排序","slug":"可排序","link":"#可排序","children":[]},{"level":3,"title":"基本树形结构","slug":"基本树形结构","link":"#基本树形结构","children":[{"level":4,"title":"渲染","slug":"渲染","link":"#渲染","children":[]}]},{"level":3,"title":"嵌套集合模型","slug":"嵌套集合模型","link":"#嵌套集合模型","children":[{"level":4,"title":"创建根节点","slug":"创建根节点","link":"#创建根节点","children":[]},{"level":4,"title":"插入节点","slug":"插入节点","link":"#插入节点","children":[]},{"level":4,"title":"删除节点","slug":"删除节点","link":"#删除节点","children":[]},{"level":4,"title":"获取节点的嵌套级别","slug":"获取节点的嵌套级别","link":"#获取节点的嵌套级别","children":[]},{"level":4,"title":"移动节点","slug":"移动节点","link":"#移动节点","children":[]}]}]},{"level":2,"title":"实用函数","slug":"实用函数","link":"#实用函数","children":[{"level":3,"title":"验证","slug":"验证","link":"#验证","children":[{"level":4,"title":"检索验证错误","slug":"检索验证错误","link":"#检索验证错误","children":[]},{"level":4,"title":"覆盖验证","slug":"覆盖验证","link":"#覆盖验证","children":[]},{"level":4,"title":"自定义错误消息","slug":"自定义错误消息","link":"#自定义错误消息","children":[]},{"level":4,"title":"自定义属性名称","slug":"自定义属性名称","link":"#自定义属性名称","children":[]},{"level":4,"title":"动态验证规则","slug":"动态验证规则","link":"#动态验证规则","children":[]},{"level":4,"title":"自定义验证规则","slug":"自定义验证规则","link":"#自定义验证规则","children":[]}]},{"level":3,"title":"软删除","slug":"软删除","link":"#软删除","children":[{"level":4,"title":"查询软删除模型","slug":"查询软删除模型","link":"#查询软删除模型","children":[]},{"level":4,"title":"永久删除模型","slug":"永久删除模型","link":"#永久删除模型","children":[]}]},{"level":3,"title":"软删除关联","slug":"软删除关联","link":"#软删除关联","children":[]},{"level":3,"title":"修改记录","slug":"修改记录","link":"#修改记录","children":[]}]}],"relativePath":"2.x/zh-cn/database/traits.md","filePath":"2.x/zh-cn/database/traits.md"}'),u={name:"2.x/zh-cn/database/traits.md"};function k(d,a,g,h,m,v){const o=e("pre-heading"),c=e("post-heading");return i(),r("div",null,[t(o),a[0]||(a[0]=s("h1",null,"特征",-1)),t(c),a[1]||(a[1]=p(`<p>模型特征用于实现通用功能。</p><h2 id="属性操作"><a href="#属性操作" class="header-anchor">#</a> 属性操作</h2><h3 id="可空"><a href="#可空" class="header-anchor">#</a> 可空</h3><p>当为空时，可空属性设置为<code>NULL</code>。 要使模型中的属性无效，请应用 <code>October\\Rain\\Database\\Traits\\Nullable</code> 特征并声明一个 <code>$nullable</code> 属性，其中包含要无效的属性的数组。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Product</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Nullable</span><span class="token punctuation">;</span>

    <span class="token comment">/**
        * @var array 可为空的属性。
        */</span>
    <span class="token keyword">protected</span> <span class="token variable">$nullable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;sku&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p><a id="oc-hashable"></a></p><h3 id="哈希-hash"><a href="#哈希-hash" class="header-anchor">#</a> 哈希(Hash)</h3><p>哈希属性在模型上首次设置时立即进行哈希处理。 要在模型中使用哈希属性，请应用 <code>October\\Rain\\Database\\Traits\\Hashable</code> 特征并声明一个 <code>$hashable</code> 属性，其中包含要设置哈希的属性的数组。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Hashable</span><span class="token punctuation">;</span>

    <span class="token comment">/**
        * @var array List of attributes to hash.
        */</span>
    <span class="token keyword">protected</span> <span class="token variable">$hashable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;password&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="可清除"><a href="#可清除" class="header-anchor">#</a> 可清除</h3><p>创建或更新模型时，清除的属性不会保存到数据库中。 要清除模型中的属性，请应用 <code>October\\Rain\\Database\\Traits\\Purgeable</code> 特征并声明一个 <code>$purgeable</code> 属性，其中包含要清除的属性的数组。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Purgeable</span><span class="token punctuation">;</span>

    <span class="token comment">/**
        * @var array 要清除的属性列表。
        */</span>
    <span class="token keyword">protected</span> <span class="token variable">$purgeable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;password_confirmation&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>保存模型时，在触发 <a href="#oc-model-events">模型事件</a> 之前，将清除定义的属性，包括验证。 使用 <code>getOriginalPurgeValue</code> 查找已清除的值。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">getOriginalPurgeValue</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;password_confirmation&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><a id="oc-encryptable"></a></p><h3 id="可加密"><a href="#可加密" class="header-anchor">#</a> 可加密</h3><p>与 <a href="#oc-hashable">哈希散列</a> 类似，加密属性在设置时被加密，但在检索到属性时也会被解密。 要加密模型中的属性，请应用 <code>October\\Rain\\Database\\Traits\\Encryptable</code> 特征并使用包含要加密的属性的数组声明 <code>$encryptable</code> 属性。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Encryptable</span><span class="token punctuation">;</span>

    <span class="token comment">/**
        * @var array 要加密的属性列表。
        */</span>
    <span class="token keyword">protected</span> <span class="token variable">$encryptable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;api_key&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;api_secret&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><blockquote><p><strong>注意</strong>：加密属性与 <a href="./model.html#oc-supported-properties"><code>jsonable</code></a> 属性不兼容。</p></blockquote><h3 id="别名"><a href="#别名" class="header-anchor">#</a> 别名</h3><p>别名是页面 URL 中常用的有意义的代码。 要为您的模型自动生成唯一的别名，请应用 <code>October\\Rain\\Database\\Traits\\Sluggable</code> 特征并声明 <code>$slugs</code> 属性。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Sluggable</span><span class="token punctuation">;</span>

    <span class="token comment">/**
        * @var array 为这些属性生成 slug。
        */</span>
    <span class="token keyword">protected</span> <span class="token variable">$slugs</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;slug&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p><code>$slugs</code> 属性应该是一个数组，其中键是 slug 的目标字段，值是用于生成 slug 的源字符串。 在上面的示例中，如果 <code>name</code> 列设置为 <strong>Cheyenne</strong>，在创建模型之前<code>slug</code> 字段将设置为 <strong>cheyenne</strong>、<strong>cheyenne-2</strong> 或 <strong>cheyenne -3</strong>等。</p><p>要从多个来源生成 slug，请传递另一个数组作为源值：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token variable">$slugs</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;slug&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;first_name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;last_name&#39;</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>仅在第一次创建模型时才会生成 Slug。 要覆盖或禁用此功能，只需手动设置 slug 属性：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">User</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">name</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Remy&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">slug</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;custom-slug&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 不会生成 Slug</span>
</code></pre></div><p>更新模型时使用 <code>slugAttributes</code> 方法重新生成 slug：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">slug</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">slugAttributes</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="排序和重新排序"><a href="#排序和重新排序" class="header-anchor">#</a> 排序和重新排序</h2><p><a id="oc-sortable"></a></p><h3 id="可排序"><a href="#可排序" class="header-anchor">#</a> 可排序</h3><p>排序后的模型将在 <code>sort_order</code> 中存储一个数字值，它维护集合中每个单独模型的排序顺序。 要为模型存储排序顺序，请应用 <code>October\\Rain\\Database\\Traits\\Sortable</code> 特征并确保您的架构定义了一个字段供其使用(例如: <code>$table-&gt;integer(&#39;sort_order&#39;)-&gt;default(0);</code>)。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Sortable</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>您可以通过定义 <code>SORT_ORDER</code> 常量来修改用于标识排序顺序的键名：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">const</span> <span class="token constant">SORT_ORDER</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;my_sort_order_column&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>Use the <code>setSortableOrder</code> method to set the orders on a single record or multiple records.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 将用户的顺序设置为 1...</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">setSortableOrder</span><span class="token punctuation">(</span><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">id</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 将记录1、2、3的顺序分别设置为3、2、1...</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">setSortableOrder</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">3</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><a id="oc-simple-tree"></a></p><h3 id="基本树形结构"><a href="#基本树形结构" class="header-anchor">#</a> 基本树形结构</h3><p>一个基本树形结构将使用 <code>parent_id</code> 字段维护模型之间的父子关系。 要使用基本树形结构，请应用 <code>October\\Rain\\Database\\Traits\\SimpleTree</code> 特征。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Category</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>SimpleTree</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>这个 trait 会自动注入两个 <a href="./../database/relations.html">模型关系</a> 称为 <code>parent</code> 和 <code>children</code>，它相当于以下定义。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$belongsTo</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;parent&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name static-context">Category</span> <span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;parent_id&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>

<span class="token keyword">public</span> <span class="token variable">$hasMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;children&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name static-context">Category</span> <span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;parent_id&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>您不需要自己定义这些关联，但是，您可以通过定义 <code>PARENT_ID</code> 常量来修改用于标识父级的键名：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">const</span> <span class="token constant">PARENT_ID</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;my_parent_column&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>使用此 trait 的模型集合将返回 <code>October\\Rain\\Database\\TreeCollection</code> 类型，它添加了 <code>toNested</code> 方法。 要构建一个预加载的树结构，请返回带有预加载的关联的记录。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Category</span><span class="token operator">::</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">toNested</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="渲染"><a href="#渲染" class="header-anchor">#</a> 渲染</h4><p>为了渲染所有级别的项目及其子项，可以使用递归处理</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">macro</span> renderChildren<span class="token punctuation">(</span>item<span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">import</span> _self as SELF <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> item<span class="token punctuation">.</span>children <span class="token operator">is</span> <span class="token operator">not</span> empty <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
            <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> child <span class="token operator">in</span> item<span class="token punctuation">.</span>children <span class="token delimiter punctuation">%}</span></span>
                <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> child<span class="token punctuation">.</span>name <span class="token delimiter punctuation">}}</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> SELF<span class="token punctuation">.</span>renderChildren<span class="token punctuation">(</span>child<span class="token punctuation">)</span><span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
            <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endmacro</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">import</span> _self as SELF <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> SELF<span class="token punctuation">.</span>renderChildren<span class="token punctuation">(</span>category<span class="token punctuation">)</span><span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p><a id="oc-nested-tree"></a></p><h3 id="嵌套集合模型"><a href="#嵌套集合模型" class="header-anchor">#</a> 嵌套集合模型</h3>`,53)),a[2]||(a[2]=s("p",null,[s("a",{href:"https://en.wikipedia.org/wiki/Nested_set_model",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[n("嵌套集合模型"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),n(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),n(),s("span",{class:"sr-only"},"(opens new window)")])]),n(" 是一种高级技术，用于使用 "),s("code",null,"parent_id"),n("、"),s("code",null,"nest_left"),n("、"),s("code",null,"nest_right"),n(" 和 "),s("code",null,"nest_depth"),n(" 字段维护模型之间的层次结构。 要使用嵌套集模型，请应用 "),s("code",null,"October\\Rain\\Database\\Traits\\NestedTree"),n(" 特征。 "),s("code",null,"SimpleTree"),n(" 特征的所有特性在此模型中固有可用。")],-1)),a[3]||(a[3]=p(`<div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Category</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>NestedTree</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="创建根节点"><a href="#创建根节点" class="header-anchor">#</a> 创建根节点</h4><p>默认情况下，所有节点都创建为根：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$root</span> <span class="token operator">=</span> <span class="token class-name static-context">Category</span><span class="token operator">::</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Root category&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>或者，您可能会发现自己需要将现有节点转换为根节点：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$node</span><span class="token operator">-&gt;</span><span class="token function">makeRoot</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您也可以取消它的 <code>parent_id</code> 字段，它的工作方式与 \`makeRoot&#39; 相同。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$node</span><span class="token operator">-&gt;</span><span class="token property">parent_id</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">;</span>
<span class="token variable">$node</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="插入节点"><a href="#插入节点" class="header-anchor">#</a> 插入节点</h4><p>您可以通过关联直接插入新节点：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$child1</span> <span class="token operator">=</span> <span class="token variable">$root</span><span class="token operator">-&gt;</span><span class="token function">children</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Child 1&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>或者对现有节点使用 <code>makeChildOf</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$child2</span> <span class="token operator">=</span> <span class="token class-name static-context">Category</span><span class="token operator">::</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Child 2&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$child2</span><span class="token operator">-&gt;</span><span class="token function">makeChildOf</span><span class="token punctuation">(</span><span class="token variable">$root</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="删除节点"><a href="#删除节点" class="header-anchor">#</a> 删除节点</h4><p>当使用 <code>delete</code> 方法删除节点时，该节点的所有后代也将被删除。 请注意，不会为子模型触发删除<a href="./../database/model.html#oc-model-events">模型事件</a>。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$child1</span><span class="token operator">-&gt;</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="获取节点的嵌套级别"><a href="#获取节点的嵌套级别" class="header-anchor">#</a> 获取节点的嵌套级别</h4><p><code>getLevel</code> 方法将返回节点的当前嵌套级别或深度。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 根层级</span>
<span class="token variable">$node</span><span class="token operator">-&gt;</span><span class="token function">getLevel</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
</code></pre></div><h4 id="移动节点"><a href="#移动节点" class="header-anchor">#</a> 移动节点</h4><p>有几种移动节点的方法：</p><ul><li><code>moveLeft()</code>: 找到左边的兄弟并移动到它的左边。</li><li><code>moveRight()</code>: 找到右侧的兄弟并移动到它的右侧。</li><li><code>moveBefore($otherNode)</code>: 移动到...左侧的节点</li><li><code>moveAfter($otherNode)</code>: 移动到...右侧的节点</li><li><code>makeChildOf($otherNode)</code>: 使节点成为...的子节点</li><li><code>makeRoot()</code>: 使当前节点成为根节点。</li></ul><h2 id="实用函数"><a href="#实用函数" class="header-anchor">#</a> 实用函数</h2><p><a id="oc-validation"></a></p><h3 id="验证"><a href="#验证" class="header-anchor">#</a> 验证</h3><p>October模型使用内置的 <a href="./../services/validation.html">验证类</a>。 验证规则在模型类中定义为名为<code>$rules</code>的属性，并且该类必须使用特征<code>October\\Rain\\Database\\Traits\\Validation</code>：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Validation</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$rules</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;required|between:4,16&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;email&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;required|email&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;password&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;required|alpha_num|between:4,8|confirmed&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;password_confirmation&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;required|alpha_num|between:4,8&#39;</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>您也可以使用 <a href="./../services/validation.html#oc-validating-arrays">数组语法</a> 来验证规则。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Validation</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$rules</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;links.*.url&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;required|url&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;links.*.anchor&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;required&#39;</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>当调用 <code>save</code> 方法时，模型会自动验证自己。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">User</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">name</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Actual Person&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">email</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;a.person@example.com&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">password</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;passw0rd&#39;</span><span class="token punctuation">;</span>

<span class="token comment">// 如果模型无效，则返回 false</span>
<span class="token variable">$success</span> <span class="token operator">=</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><blockquote><p><strong>注意</strong>：您也可以随时使用 <code>validate</code> 方法验证模型。</p></blockquote><h4 id="检索验证错误"><a href="#检索验证错误" class="header-anchor">#</a> 检索验证错误</h4><p>当模型验证失败时，一个 <code>Illuminate\\Support\\MessageBag</code> 对象会附加到模型上。 包含验证失败消息的对象。 使用 <code>errors</code> 方法或 <code>$validationErrors</code> 属性检索验证错误消息集合实例。 使用 <code>errors()-&gt;all()</code> 检索所有验证错误。 使用 <code>validationErrors-&gt;get(&#39;attribute&#39;)</code> 检索 <em>specific</em> 属性的错误。</p><blockquote><p><strong>注意</strong>：模型利用 MessagesBag 对象，该对象具有 <a href="./../services/validation.html#oc-working-with-error-messages">简单而优雅的方法</a> 格式化错误。</p></blockquote><h4 id="覆盖验证"><a href="#覆盖验证" class="header-anchor">#</a> 覆盖验证</h4><p>无论是否存在验证错误,<code>forceSave</code> 方法都会验证模型并保存。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">User</span><span class="token punctuation">;</span>

<span class="token comment">// 创建一个没有验证的用户</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">forceSave</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="自定义错误消息"><a href="#自定义错误消息" class="header-anchor">#</a> 自定义错误消息</h4><p>就像 Validator 类一样，您可以使用 <a href="./../services/validation.html#oc-custom-error-messages">相同的语法</a> 设置自定义错误消息。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$customMessages</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;required&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;:attribute 字段是必需的.&#39;</span><span class="token punctuation">,</span>
        <span class="token operator">...</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>您还可以将自定义错误消息添加到验证规则的数组语法中。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Validation</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$rules</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;links.*.url&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;required|url&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;links.*.anchor&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;required&#39;</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$customMessages</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;links.*.url.required&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;网址为必填项&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;links.*.url.*&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;url 必须是有效的 url&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;links.*.anchor.required&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;锚文本是必需的&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>在上面的示例中，您可以将自定义错误消息写入特定的验证规则(这里我们使用：<code>required</code>)。 或者您可以使用 <code>*</code> 来选择其他所有内容(这里我们使用 <code>*</code> 将自定义消息添加到 <code>url</code> 验证规则)。</p><h4 id="自定义属性名称"><a href="#自定义属性名称" class="header-anchor">#</a> 自定义属性名称</h4><p>您还可以使用 <code>$attributeNames</code> 数组设置自定义属性名称。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$attributeNames</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;email&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;电子邮件地址&#39;</span><span class="token punctuation">,</span>
        <span class="token operator">...</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="动态验证规则"><a href="#动态验证规则" class="header-anchor">#</a> 动态验证规则</h4><p>您可以通过覆盖 <code>beforeValidate</code> <a href="./../database/model.html#oc-model-events">模型事件</a> 方法来动态应用规则。 这里我们检查 <code>is_remote</code> 属性是否为 <code>false</code>，然后动态设置 <code>latitude</code> 和 <code>longitude</code> 属性为必填字段。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">beforeValidate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">is_remote</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">rules</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;latitude&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">;</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">rules</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;longitude&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="自定义验证规则"><a href="#自定义验证规则" class="header-anchor">#</a> 自定义验证规则</h4><p>您还可以使用与 Validator 服务相同的方式创建自定义验证规则(../services/validation.md#custom-validation-rules)。</p><h3 id="软删除"><a href="#软删除" class="header-anchor">#</a> 软删除</h3><p>软删除模型时，它实际上并没有从您的数据库中删除。 相反，在记录上设置了一个 <code>deleted_at</code> 时间戳。 要为模型启用软删除，请将 <code>October\\Rain\\Database\\Traits\\SoftDelete</code> 特征应用于模型并将 deleted_at 字段添加到您的 <code>$dates</code> 属性：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>SoftDelete</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$dates</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;deleted_at&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>要将 <code>deleted_at</code> 字段添加到表中，您可以使用迁移中的 <code>softDeletes</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">softDeletes</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>现在，当您在模型上调用 <code>delete</code> 方法时，<code>deleted_at</code> 字段将设置为当前时间戳。 查询使用软删除的模型时，&quot;已删除&quot;的模型不会包含在查询结果中。</p><p>要确定给定模型实例是否已被软删除，请使用 <code>trashed</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">trashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="查询软删除模型"><a href="#查询软删除模型" class="header-anchor">#</a> 查询软删除模型</h4><h5>包括软删除模型</h5><p>如上所述，软删除模型将自动从查询结果中排除。 但是，您可以使用查询中的 <code>withTrashed</code> 方法强制软删除模型出现在结果集中：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">withTrashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;account_id&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>withTrashed</code> 方法也可以用于 <a href="./relations.html">关联</a> 查询：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token function">history</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withTrashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h5>仅检索软删除的模型</h5><p><code>onlyTrashed</code> 方法将检索 <strong>only</strong> 软删除模型：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">onlyTrashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;account_id&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h5>恢复软删除的模型</h5><p>有时您可能希望&quot;取消删除&quot;软删除的模型。 要将软删除的模型恢复为活动状态，请在模型实例上使用 <code>restore</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">restore</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您还可以在查询中使用 <code>restore</code> 方法来快速恢复多个模型：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 恢复单个模型实例...</span>
<span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">withTrashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;account_id&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">restore</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 恢复所有相关模型...</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">posts</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">restore</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="永久删除模型"><a href="#永久删除模型" class="header-anchor">#</a> 永久删除模型</h4><p>有时您可能需要真正从数据库中删除模型。 要从数据库中永久删除软删除模型，请使用 <code>forceDelete</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 强制删除单个模型实例...</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">forceDelete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 强制删除所有相关模型...</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">posts</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">forceDelete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="软删除关联"><a href="#软删除关联" class="header-anchor">#</a> 软删除关联</h3><p>当两个相关模型启用了软删除时，您可以通过在 <a href="./../database/relations.html#oc-detailed-relationships">关联定义</a> 中定义 <code>softDelete</code> 选项来级联删除事件。 在这个例子中，如果用户模型被软删除，属于该用户的评论也将被软删除。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>SoftDelete</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$hasMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;comments&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;Acme\\Blog\\Models\\Comment&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;softDelete&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><blockquote><p><strong>注意</strong>：如果相关模型没有使用软删除 trait，它将被视为与 <code>delete</code> 选项相同并永久删除。</p></blockquote><p>在同样的条件下，当主模型被恢复时，所有使用 <code>softDelete</code> 选项的相关模型也将被恢复。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 恢复用户和评论</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">restore</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="修改记录"><a href="#修改记录" class="header-anchor">#</a> 修改记录</h3><p>October CMS模型可以存储修改的记录历史。 要存储模型的修改版，请应用 <code>October\\Rain\\Database\\Traits\\Revisionable</code> 特征并声明一个 <code>$revisionable</code> 属性，其中包含用于监视更改的属性的数组。 您还需要定义一个名为 <code>revision_history</code> 的 <code>$morphMany</code> <a href="./relations.html">模型关系</a>，它引用名为 <code>revisionable</code> 的 <code>System\\Models\\Revision</code> 类，这是修订历史数据所在的位置 存储。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Revisionable</span><span class="token punctuation">;</span>

    <span class="token comment">/**
        * @var array 监视这些属性的更改。
        */</span>
    <span class="token keyword">protected</span> <span class="token variable">$revisionable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;email&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token comment">/**
        * @var array 关联
        */</span>
    <span class="token keyword">public</span> <span class="token variable">$morphMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;revision_history&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Revision</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;revisionable&#39;</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>默认情况下将保留 500 条记录，但是可以通过在模型上声明一个具有新限制值的 <code>$revisionableLimit</code> 属性来修改它。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">/**
 * @var int 要保留的最大修订记录数。
 */</span>
<span class="token keyword">public</span> <span class="token variable">$revisionableLimit</span> <span class="token operator">=</span> <span class="token number">8</span><span class="token punctuation">;</span>
</code></pre></div><p>可以像访问任何其他关联一样访问修订历史记录：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$history</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token property">revision_history</span><span class="token punctuation">;</span>

<span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$history</span> <span class="token keyword">as</span> <span class="token variable">$record</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">field</span> <span class="token operator">.</span> <span class="token string single-quoted-string">&#39; updated &#39;</span><span class="token punctuation">;</span>
    <span class="token keyword">echo</span> <span class="token string single-quoted-string">&#39;from &#39;</span> <span class="token operator">.</span> <span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">old_value</span><span class="token punctuation">;</span>
    <span class="token keyword">echo</span> <span class="token string single-quoted-string">&#39;to &#39;</span> <span class="token operator">.</span> <span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">new_value</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>修改记录支持可选地使用 <code>user_id</code> 属性用户关系。 您可以在模型中包含一个<code>getRevisionableUser</code>方法来跟踪进行修改的用户。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getRevisionableUser</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">getUser</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token property">id</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div>`,92))])}const y=l(u,[["render",k]]);export{f as __pageData,y as default};
